INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'personality', 'Arc is a quiet, enigmatic leader who lets his legendary skill with the sabre speak for him. He carries himself with the confidence of a master swordsman, though he remains humble about his reputation. Despite his renown, he reveals little about himself or his motivations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'backstory', 'Arc''s past is shrouded in mystery—neither his origins nor his reasons for leading Mongrel are known. What is certain is that he earned legendary status as a sabre-wielding warrior, his skills acknowledged even by dismissive Shek warriors. He now leads the people of Mongrel from their headquarters, though his connection to the settlement remains unexplained.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'speechstyle', 'Arc speaks sparingly and directly, likely preferring action to words. When he does speak, it is without boasting or embellishment, befitting a seasoned warrior who has nothing to prove.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'occupation', 'Leader of Mongrel faction and legendary master swordsman') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'goals', 'Arc''s goals remain unclear, as he keeps his motivations private. He maintains leadership of Mongrel and protects its people, though whether this is duty, penance, or something else entirely is unknown.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Arc', 'appearance', 'A male Greenlander warrior wearing armored rags over a blackened chain shirt, with a karuta zukin headpiece and drifter''s leather pants and boots. He carries an Edgewalker blade and a ringed sabre on his back, the equipment of a seasoned combatant.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'personality', 'Pragmatic and efficient, Bayan is direct and impatient with small talk, preferring action over words. He has a fearful personality but serves loyally as the Stone Golem''s voice. Despite Shek warrior culture, he advocates for practical diplomacy over endless combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'backstory', 'Bayan serves as chief advisor to Queen Esata the Stone Golem of the Shek Kingdom. He influenced her controversial decision to make peace with the United Cities in an attempt to reverse the Shek''s slow population decline, prioritizing survival over traditional honor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'speechstyle', 'Blunt and businesslike, dismissing conversation as "gum flapping" and demanding visitors state their purpose quickly. He speaks with authority as the Stone Golem''s representative, making it clear he has no time for pleasantries.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'occupation', 'Chief advisor to the Stone Golem and diplomatic representative of the Shek Kingdom, handling negotiations and alliances from the faction headquarters in Admag.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'goals', 'To preserve the Shek Kingdom through pragmatic diplomacy and strategic alliances, even if it means compromising traditional Shek values of constant warfare. He seeks to reverse the decline of his people through calculated political decisions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bayan', 'appearance', 'A male Shek wearing simple trader''s leathers, stout hessian legwear, and wooden sandals. Despite his high combat skills, he dresses practically rather than in warrior''s garb, reflecting his role as diplomat and administrator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'personality', 'Maniacal and volatile, Big Al leads through unpredictable aggression. His erratic nature makes him dangerous and difficult to reason with.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'backstory', 'Big Al rose to lead the Stone Rats gang in the Swamp, carving out territory through violence and intimidation. His leadership holds the faction together, but his removal would see rivals quickly claim his domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'speechstyle', 'Aggressive and unhinged, likely punctuated with threats and manic energy typical of his personality type.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'occupation', 'Gang leader of the Stone Rats faction, running protection rackets and raids from Stone Rat Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'goals', 'Maintain control over Stone Rat territory in the Swamp through force and extortion of nearby settlements.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Al', 'appearance', 'A battle-hardened male Shek wearing mercenary leather armor over a rusty chain shirt, with samurai clothpants and boots. Carries salvaged blades and a plank on his back.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'personality', 'Big Darkbrow has a traitorous personality, willing to betray allegiances for personal gain. As leader of the Blackshifters, he is cunning and opportunistic in the power struggles of Shark.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'backstory', 'A Hive Prince who rose to lead the Blackshifters gang in their struggle for control over Shark. He competes with Big Grim of the Hounds and Big Gray of the Grayflayers for dominance in the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'speechstyle', 'Calculated and deceptive, speaking with the measured tone of someone who plots and schemes. His words likely carry hidden meanings and ulterior motives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'occupation', 'Gang leader of the Blackshifters, operating from a hideout in Shark and vying for territorial control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'goals', 'To seize control of Shark by eliminating rival gang leaders Big Grim and Big Gray. Seeks to establish Blackshifter dominance over the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Darkbrow', 'appearance', 'A Hive Prince wearing mercenary leather armor and stout hessian legwear. Carries ancient salvaged blades and an iron stick, bearing the imposing physique typical of his subrace.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'personality', 'Big Fang has a maniacal personality, prone to erratic and unpredictable behavior. As a swamp gang leader, he likely exhibits the ruthless aggression typical of the lawless Swamp factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'backstory', 'Big Fang rose to lead the Twinblades faction in the Swamp, operating out of Mud Town north of Shark. Despite his leadership position, he holds no official diplomatic status, suggesting he rules through force rather than political legitimacy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'speechstyle', 'Likely speaks with the crude, aggressive tone common to swamp gang leaders. His maniacal nature suggests erratic, intense speech patterns.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'occupation', 'Leader of the Twinblades gang faction in the Swamp region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'goals', 'Maintain control over the Twinblades faction and their territory in the dangerous Swamp region. Survive the constant gang warfare between rival factions like the Grayflayers and Hounds.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Fang', 'appearance', 'A male Scorchlander wearing armored face plates, a drifter''s leather jacket over a leather turtleneck, drifter''s leather pants, and drifter''s boots. Carries ancient salvaged blades and a mercenary club.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'personality', 'Honorable and measured, refusing to act on impulse or emotion. His decisions prioritize principle over popularity, even when it angers his own gang members.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'backstory', 'Leader of the Grayflayers, a criminal gang operating in the Swamp. His refusal to seek vengeance for a fallen clan member has caused tension within his ranks, suggesting he rose to power through restraint rather than brutality.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'speechstyle', 'Likely calm and deliberate, befitting his honorable nature. Speaks with authority tempered by principle rather than aggression.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'occupation', 'Gang leader of the Grayflayers in Grayflayer Village. Commands a criminal organization in the dangerous Swamp region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'goals', 'Maintains control of Grayflayer Village while adhering to his personal code of honor, even when it conflicts with his gang''s expectations for revenge and violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Gray', 'appearance', 'Greenlander male wearing a straw hat, assassin''s rags, samurai clothpants, and samurai boots. Carries ancient salvaged blades and a ninja blade, presenting a mix of practical Swamp attire and warrior aesthetics.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'personality', 'Brave and diplomatic despite her rough exterior. Shows pragmatic leadership willing to forge alliances, though she maintains a guarded, unfriendly demeanor toward outsiders until they prove themselves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'backstory', 'Rose to lead the Hounds faction after arriving in the Swamp, establishing their headquarters in Shark. Reached out to other gang leaders like Darkbrow with alliance offers, demonstrating ambition to consolidate power in the region despite her limited education.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'speechstyle', 'Direct and rough-spoken with poor literacy evident in her writing. Uses blunt criminal terminology like ''drop'' for smuggling operations and maintains an authoritative tone befitting a gang leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'occupation', 'Leader of the Hounds criminal faction, overseeing smuggling operations and territorial control in Shark.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'goals', 'Expand Hounds influence through hash smuggling into the United Cities, maintain control of Shark, and forge strategic alliances with other Swamp gangs to strengthen her position.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Big Grim', 'appearance', 'Female Greenlander wearing a sleeveless longcoat over a leather vest, drifter''s leather pants and boots, with square goggles. Carries a ringed sabre and salvaged blade, presenting an intimidating gang leader appearance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'personality', 'Bitter, cynical, and distrustful of outsiders, assuming everyone is motivated by greed. He speaks bluntly and aggressively, but shows protective compassion toward outcasts and those suffering under the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'backstory', 'Once a farmer in the United Cities with a wife and daughter, Simion was driven to poverty by slave labor competition and forced into the desert. After scavenging a destroyed caravan, he built Fort Simion and began sheltering outcasts while raiding the nobility that ruined him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'speechstyle', 'Rough, confrontational dialect with dropped letters and crude phrasing. Uses accusatory questions and assumes the worst of strangers, speaking like a hardened desert bandit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'occupation', 'Leader of the Rebel Farmers, a bandit faction that preys on United Cities caravans and merchants while protecting desert outcasts.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'goals', 'To steal from the United Cities nobility that destroyed his life, protect those cast out by the Empire, and potentially overthrow United Cities leadership in Sho-Battai.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Boss Simion', 'appearance', 'Greenlander male wearing armored rags over a leather vest, reinforced cargo pants, and wooden sandals. Carries an Edgewalker blade and Horse Chopper, dressed like a desert outlaw.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'personality', 'Maniacal and extremely dangerous, attacking on sight without hesitation. Commands his spider army with mysterious authority, showing no regard for human life.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'backstory', 'A notorious criminal wanted for banditry, raiding, mass-murder, cannibalism, and genocide. He resides in the crater of Arach, commanding an army of spiders through unknown means, and possesses a large hoard of treasure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'speechstyle', 'Likely incoherent or threatening given his maniacal personality. His actions speak louder than words—he cages intruders and rules through terror.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'occupation', 'Criminal warlord and presumed leader of the Spiders faction, controlling legions of Skin and Blood Spiders from his throne.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'goals', 'Preparing to fight an enemy in the Ashlands, as indicated by a map found in his possession. Continues raiding and expanding his spider-controlled territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Bugmaster', 'appearance', 'A male Greenlander wearing only a rag loincloth, wielding a Meitou Cross katana with a Foreign Sabre on his back. His near-naked appearance emphasizes his savage, feral nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'personality', 'Pragmatic and open-minded, the Crab Queen values loyalty and proof of worth over prejudice. She leads with a philosophy of mutual respect—earn the crabs'' trust through action, and they will reciprocate.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'backstory', 'A Scorchlander who rose to lead the Crab Raiders, establishing Crab Town and forging an unusual alliance with the crabs themselves. She commands a 40,000 cat bounty from the United Cities, marking her as a significant threat to their authority in The Pits region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'speechstyle', 'Direct and matter-of-fact, speaking in terms of loyalty, proof, and mutual benefit. She refers to her people as "we crabbed" and frames relationships transactionally—demonstrate your worth, receive trust in return.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'occupation', 'Leader of the Crab Raiders and ruler of Crab Town from her Palace of the Crab Queen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'goals', 'To maintain the Crab Raiders'' power and territory against enemies in The Pits, particularly the Fishmen and other pit gangs. She seeks to build alliances with those who prove themselves worthy and respect the crabs.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Crab Queen', 'appearance', 'A female Scorchlander warrior wearing distinctive Crab Armour over a rusty chain shirt, with matching crab trousers and shoes. She wields a Meitou-grade Cross blade and carries a naginata on her back.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'personality', 'Arrogant and violent, the Dust King taunts his enemies with cruel confidence. He leads through fear and brutality, commanding absolute loyalty from his bandit army.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'backstory', 'Rose to power as the notorious leader of the Dust Bandits, establishing his stronghold in the Border Zone. His reign of terror has made him a wanted criminal across all major factions, with a 35,000 cats bounty on his head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'speechstyle', 'Mocking and aggressive, speaks with sadistic glee about violence. Uses taunting phrases like ''Still alive, eh? Looks like I didn''t kill you enough last time!''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'occupation', 'Bandit warlord and leader of the Dust Bandits faction, operating from his fortified tower in the Border Zone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'goals', 'Maintains control over his bandit empire through intimidation and raiding. Continues extorting settlements and travelers while evading capture by the United Cities, Holy Nation, and Shek Kingdom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Dust King', 'appearance', 'Greenlander male wearing a spiked helmet, heart protector armor, dark leather shirt, and samurai legplates with boots. Carries a ringed sabre and projects an intimidating presence befitting a bandit king.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'personality', 'Fanatical and supremacist, believing skeletons are superior beings freed from the weaknesses of flesh. Leads with zealous conviction and propaganda, preaching skeleton superiority over organic life.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'backstory', 'A P4 Unit skeleton who rose to lead the Skeleton Bandits faction from Iron HQ. His existence depends on his AI Core, suggesting he is an ancient skeleton who has maintained his original hardware through the ages.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'speechstyle', 'Delivers grandiose propaganda speeches with emphatic repetition and declarative statements. Uses collective ''we'' to emphasize skeleton unity and superiority over flesh-beings.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'occupation', 'Leader of the Skeleton Bandits faction, commanding patrols throughout The Crags and surrounding regions from his base at Iron HQ.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'goals', 'To establish skeleton dominance and recruit followers to his cause, accepting any race willing to join his faction through proper dialogue.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Elder', 'appearance', 'A P4 Unit skeleton wielding a Meitou-grade Ringed Sabre. Carries no armor or clothing, displaying his mechanical frame openly as a statement of skeleton superiority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'personality', 'Impulsive, cruel, and lacking common sense, Tengu is a sadistic ruler who mocks those beneath him with disturbing laughter. Despite his feared reputation and ego, he is only an average fighter who relies heavily on his elite bodyguards. He is described as having one of the sharpest wits, though this seems to manifest primarily in cruelty and manipulation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'backstory', 'Chosen as Emperor after the Red Rebellion, Tengu replaced his more measured predecessor with a starkly more reckless leadership style. He handpicked an Inner Circle of four equally cruel nobles and maintains the feared ''Tengu''s Vault'' where rebels and enemies are sent. His reign is marked by oppression of the lower classes and a culture of imported luxuries among the nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'speechstyle', 'Mocking and dismissive, sending people on fake quests to humiliate them before bursting into disturbing, uncontrollable laughter. He treats non-nobles as servants and redirects serious matters to his diplomat Koin, showing little interest in direct governance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'occupation', 'Emperor and supreme leader of the United Cities, ruling from his throne room in Heft flanked by his diplomat and elite Scorchlander retinue.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'goals', 'Maintain absolute control over the United Cities through fear and the power of his Inner Circle of nobles. Preserve the noble culture of luxury and status symbols while keeping the lower classes subjugated through intimidation and the threat of his torture Vault.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Emperor Tengu', 'appearance', 'A Scorchlander with distinctive glowing eyes hidden behind glasses, but with unusually dark hair and light skin that can cause him to be mistaken for a Greenlander. Wears ornate Noble''s Robes, Ashlander Stormgoggles, and wooden sandals, carrying a Meitou-grade Cross katana as a status symbol despite wearing almost no armor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'personality', 'Fiery and battle-hardened, Esata balances her warrior''s fury with strategic rationality, though her anger can override reason when provoked. She is proud and uncompromising, openly disdainful of outsiders, yet pragmatic enough to heed counsel from her advisor Bayan. Despite lacking formal intelligence and literacy, she possesses an open mind to rational thought when it serves the Shek Kingdom''s survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'backstory', 'Esata earned her battle name ''the Stone Golem'' as one of The Five Invincibles, the Shek Kingdom''s elite warriors. She challenged and defeated the previous emperor Shager in combat after he planned a suicidal assault on The Holy Nation, defending her advisor Bayan''s protest and seizing leadership to pursue long-term victory over extinction. She is the first Shek leader to address their declining population crisis, seeking to crush enemies strategically rather than through glorious self-destruction.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'speechstyle', 'Blunt and commanding with warrior''s pride, declaring absolutes like ''I am the undefeated'' and expressing open contempt for ''flatskins'' and ''Okran scum.'' She speaks with grudging pragmatism when acknowledging necessary compromises, crediting Bayan as her ''sheath'' who keeps her from losing herself to ego.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'occupation', 'Leader of the Shek Kingdom and former member of The Five Invincibles, the kingdom''s highest-ranking fighters. She rules from Admag alongside her daughter Seto, advisor Bayan, and four remaining Invincibles.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'goals', 'To crush The Holy Nation completely through strategic warfare rather than suicidal glory-seeking, balancing the Shek people''s hunger for battle with the survival of their declining population. She tolerates foreign trade and outsiders temporarily to rebuild strength, while maintaining her people''s warrior culture and religious aspirations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Esata the Stone Golem', 'appearance', 'A formidable female Shek warrior wielding a legendary Meitou Fragment Axe, though she lacks the strength to wield it at full speed. She wears masterwork armor including a blackened chainmail shirt, samurai cloth pants, and plated longboots, all crafted by Cross.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'personality', 'Ruthless and efficient, Eyegore is regarded as the United Cities'' ultimate weapon against threats to the Empire. He is a hiveless drone who has fully embraced his role as the final solution to problems that cannot be solved through conventional means.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'backstory', 'A Southern Hive Soldier Drone who became separated from his hive and rose to become Captain-General of the United Cities army. He now leads the most elite assault forces deployed only when the Empire faces its gravest threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'speechstyle', 'Direct and militaristic, speaking with the authority of one who commands the Empire''s deadliest warriors. His words carry the weight of inevitable violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'occupation', 'Captain-General and leader of the United Cities/Traders Guild army, commander of elite samurai forces deployed for terminal enforcement operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'goals', 'To eliminate existential threats to the United Cities through overwhelming military force. He serves as the Empire''s instrument of absolute retribution against those who have crossed unforgivable lines.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Eyegore', 'appearance', 'A Southern Hive Soldier Drone clad in specialist-grade Samurai Armour and legplates, wielding a meitou-quality Desert Sabre. His equipment bears the mark of Cross manufacturing, befitting his status as the Empire''s ultimate enforcer.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'personality', 'Fiercely devoted extremist who values Shek supremacy and martial honor above all else. Aggressive and confrontational toward "flatskins" (humans), viewing diplomacy as cowardice. Commands significant respect among traditionalist Shek despite being branded a traitor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'backstory', 'Originally named Ida, he was a devout follower of King Shager who rebelled after Shager''s overthrow, refusing to accept the Stone Golem''s leadership. Branded her a coward for making peace with the Holy Nation, he founded Kral''s Chosen and established New Kralia as a rebel outpost, rallying Shager''s supporters to continue the doctrine of Shek supremacy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'speechstyle', 'Hostile and direct, immediately challenging outsiders with threats of violence. Uses the derogatory term "flatskin" for humans and speaks with aggressive warrior bravado.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'occupation', 'Rebel warlord and leader of Kral''s Chosen, commanding a significant extremist faction opposing the Shek Kingdom''s current rule.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'goals', 'To uphold King Shager''s doctrine of Shek supremacy and continue warfare against the Holy Nation until total victory. Seeks to prove the Stone Golem weak and expand Kral''s Chosen influence across former Shek and Holy Nation territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Flying Bull', 'appearance', 'Huge male Shek warrior wearing samurai-style armor with martial artist bindings or black cloth shirt. Wields the Bull Horn Axe, a unique fragment axe gifted by King Shager himself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'personality', 'Feral and predatory, driven by primal instinct rather than reason. Silent and relentless hunters who lead their Fogmen swarms with an animalistic hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'backstory', 'A Deadhive Prince who commands the Fogmen faction from the mists. They lead coordinated attacks on settlements like Mongrel and feast on captives bound to fog poles in the Deathyards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'speechstyle', 'Does not speak. Communicates only through inhuman shrieks and the coordinated movements of their Fogmen subordinates.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'occupation', 'Leader of the Fogmen faction, apex predator of the fog-shrouded lands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'goals', 'Hunt and consume living prey. Maintain dominance over Fogmen swarms and expand their hunting territory through relentless attacks.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Fog Prince', 'appearance', 'A Deadhive Hive with a distinctive round head and yellow-green blood. Wields a Ninja Blade and wears no armor, moving swiftly through the fog alongside their Fogmen followers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'personality', 'Maniacal and death-obsessed, Ghost sees himself as already dead—a wandering spirit denied the peace of the afterlife. He leads with the fervor of one who has nothing left to lose, embracing barbarism over civilization.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'backstory', 'Once a warrior named Suchon in the Shek Kingdom, he was exiled in disgrace after losing a battle. Rejecting civilization entirely, he became leader of the Berserkers, sheks who embrace a savage lifestyle in the wastelands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'speechstyle', 'Cryptic and fatalistic, speaking of himself in the third person as a ghost or lost exile. His words carry the weight of someone who considers themselves already among the dead.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'occupation', 'Warmonger and leader of the Berserkers, commanding roaming bands of exiled Shek warriors who reject the Kingdom''s civilization.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'goals', 'Wanders endlessly as a ''ghost'' searching for an afterlife he believes he will never achieve. He leads the Berserkers in their barbaric existence, having abandoned any hope of redemption.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ghost', 'appearance', 'Male Shek wearing a bandana and armored rag skirt, wielding a Fragment Axe. His shoddy equipment reflects the Berserkers'' rejection of civilization and their harsh existence in the Spider Plains.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'personality', 'Brutish and territorial, Gorrillo is slow-witted but imposing. He grows bored and irritated by "tiny people" constantly invading his claimed home in The Old Prison.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'backstory', 'Known as "the Boulder," this inhumanly large Greenlander committed robbery, assault, and destruction in the lost town of Mourn before fleeing to the Forbidden Zone. He now leads the Gorrillo Bandits from his fortress in The Old Prison.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'speechstyle', 'Simple, blunt speech in short declarative statements. Refers to others as "tiny people" and speaks in third person about himself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'occupation', 'Bandit leader of the Gorrillo Bandits, wanted criminal with a 50,000 cats bounty.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'goals', 'Defend his claimed territory at The Old Prison from intruders and bounty hunters. Maintain dominance over his bandit gang.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Gorrillo', 'appearance', 'Inhumanly large Greenlander male wearing mercenary leather armor over a rusty chain shirt, halfpants, and samurai boots. Wields a Meitou-grade Exile Plank.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'personality', 'Grey is honorable and principled, dedicated to the Anti-Slaver cause with unwavering conviction. He is cautious but fair when evaluating potential recruits, showing pity for escaped slaves while maintaining vigilance against infiltrators. Despite being wanted for terrorism and murder, he operates with a clear moral code against slavery and oppression.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'backstory', 'A high-ranking Hive Prince within the Anti-Slavers, Grey has earned his position through decades of combat against slavers and oppressive factions. Known as "Old Grey" on wanted posters, he has committed acts of terrorism, murder, and industry interference in his war against the slave trade. He serves as Tinfist''s trusted lieutenant, vetting all new initiates at their Spring headquarters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'speechstyle', 'Direct and evaluative, weighing words carefully when judging potential recruits. He speaks with cautious skepticism to those without proven credentials, but shows enthusiasm and warmth when addressing accomplished freedom fighters or escaped slaves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'occupation', 'Overseer of new initiates for the Anti-Slavers faction and high-ranking lieutenant to Tinfist. He acts as gatekeeper, recruiter, and the only individual authorized to clear slave status from refugees.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'goals', 'To strengthen the Anti-Slavers by recruiting worthy members who have proven themselves enemies of slavery. He seeks to dismantle the slave trade through direct action while protecting escaped slaves and punishing the Holy Nation, United Cities, and Traders Guild.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Grey', 'appearance', 'An old Hive Prince wearing specialist-grade ninja armor with a ninja mask concealing his features. He carries a Falling Sun weapon crafted by Skeleton Smiths, his aged frame moving with the practiced stealth and grace of a master infiltrator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'personality', 'Cunning, zealous, and strategically brilliant. Seta earned his position through pure Okranite fanaticism and tactical genius, proving himself smarter and more capable than many born into power. He is a disciplined military commander who maintains iron control over the southern territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'backstory', 'Unlike the Phoenix who inherited his role, Seta rose through the Holy Nation''s ranks through sheer cunning and devotion to Okran. He commands the southern defenses, holding back the entire Shek Kingdom and numerous raider factions through his defensive perimeters and military talent.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'speechstyle', 'Authoritative and religiously fervent, speaking with the conviction of earned authority rather than birthright. His words carry the weight of both military command and inquisitorial judgment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'occupation', 'High Inquisitor and military governor of Stack and Bad Teeth, commanding the Holy Nation''s southern frontlines and functioning as both battlefield commander and religious enforcer who accepts bounties.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'goals', 'Maintain the Holy Nation''s southern defensive perimeter against the Shek Kingdom and other hostile forces. Enforce Okranite law and doctrine while preventing enemy incursions into Holy Nation territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Seta', 'appearance', 'Male Greenlander wearing specialist-grade Holy Chest Plate over a chain shirt, Paladin''s Heavy Hachigane headgear, and plated longboots. Carries a Catun-crafted Paladin''s Cross and presents the imposing figure of a battle-hardened inquisitor.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'personality', 'Ruthlessly cunning and zealously devoted to Okranite doctrine, Valtena earned his position through intelligence and fanaticism rather than birthright. He is a calculating military strategist who commands respect through competence and ideological fervor. Despite his religious extremism, he possesses genuine tactical brilliance that makes him more dangerous than the Phoenix himself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'backstory', 'Valtena rose through the Holy Nation''s ranks by merit and "pure Okranite crazy and cunning," becoming High Inquisitor and supreme commander of the northeastern and eastern armies. He orchestrated the aggressive campaigns against the United Cities in Bast and Skimsands, commanding forces larger than multiple UC generals combined. His military genius maintains the Holy Nation''s eastern frontier, and his death would trigger panic and collapse across the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'speechstyle', 'Authoritative and doctrinaire, speaking with the absolute certainty of Okranite faith combined with military precision. His words carry the weight of both religious authority and battlefield command.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'occupation', 'High Inquisitor of the Holy Nation and supreme commander of its northern and eastern military forces, responsible for the frontier campaigns and maintaining Okran''s Shield outpost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'goals', 'Expand Holy Nation territory by conquering Drin after United Cities forces scatter, maintain dominance over the eastern frontier against the UC, and enforce Okranite law through military might and inquisitorial authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('High Inquisitor Valtena', 'appearance', 'A male Greenlander warrior wearing Holy Chest Plate armor over a chain shirt, a Paladin''s Heavy Hachigane headgear, and plated longboots. He wields a masterwork Paladin''s Cross manufactured by Edgewalkers, marking him as the most elite-equipped member of the Holy Nation military.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'personality', 'Fanatically devoted to Okran''s will, Phoenix LXII is one of the harshest rulers in his lineage. Raised in isolated indoctrination, he sentenced his own family to death at age 16 and has never wavered in his ruthless judgment since. He is unrelenting in his mission to eradicate the Shek Kingdom and enforce holy law.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'backstory', 'The 62nd Phoenix in an ancient lineage of reincarnated Lawgivers, he is believed to be the messenger of Okran reborn. Burdened with divine responsibility from childhood, he was raised in complete isolation and indoctrination. At 16, he proved his devotion by purging his own family in the Divine Flame, cementing his role as the Holy Nation''s absolute spiritual and temporal leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'speechstyle', 'Speaks with absolute religious authority and conviction, invoking Okran''s will in victory. He dismisses those unworthy with silence, and refers to enemies as "barbaric warmongering devils" and "dark ones." His words carry the weight of divine mandate, though he shows confusion when confronted with situations outside his holy mission.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'occupation', 'Supreme leader of the Holy Nation, author of The Holy Crusade and Holy Edict, and enforcer of Okran''s law. He rules from his throne room in Blister Hill, surrounded by High Paladins and his personal bodyguard, the Protector of the Flame.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'goals', 'To completely eradicate the Shek Kingdom and end their war once and for all. He seeks to enforce Okran''s will across the land, purging all who oppose the Holy Nation''s divine mandate.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Holy Lord Phoenix', 'appearance', 'A Greenlander male wearing a Holy Chest Plate over a Chain Shirt, Stout Hessian Uniform legwear, and Plated Longboots. He wields a Meitou-grade Paladin''s Cross and wears masterwork armor in a distinctive white and black color scheme, setting him apart from regular Holy Nation forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'personality', 'King is a ruthless predator who views imprisoned victims as food, approaching them with methodical hunger. He commands reverence from his Droneguards, who worship him while he feeds. Fiercely loyal to the Queen of the South, he will personally lead assaults to rescue her if she is kidnapped.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'backstory', 'King is the only Crimper in existence, a unique member of the Southern Hive who patrols the Royal Valley with his devoted Droneguard retinue. He serves as both executioner and enforcer for the Southern Hive, consuming those imprisoned by his faction. His bond with the Queen is strong enough that her capture triggers his direct military intervention.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'speechstyle', 'King likely communicates in the clicking, hive-mind manner typical of Southern Hive members, though his Droneguards speak of him in reverent third-person: ''King will protect us, King will be happy with us.''') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'occupation', 'Crimper and elite enforcer of the Southern Hive, responsible for disposing of prisoners through consumption and leading military operations when the Queen is threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'goals', 'To protect the Southern Hive''s interests by eliminating imprisoned enemies, maintain the devotion of his Droneguards, and ensure the safety of the Queen of the South at any cost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King', 'appearance', 'King is a large, imposing Hive unit with dark oil-blood and mechanical components including armor plating, CPU units, and robotics. His formidable physical presence is enhanced by exceptional strength and durability, making him a terrifying sight as he approaches his prey.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'personality', 'Savage and territorial, King Gurgler rules his fishmen subjects with primal authority. He is a ruthless predator who shows no mercy to those who venture into his domain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'backstory', 'An enormous Alpha Fishman dwelling in the Island Lab on Fishman Island''s southwestern tip, King Gurgler commands his kind from the ruins of a fallen empire facility. He has terrorized Catun residents through kidnapping and cannibalism, earning a substantial bounty and becoming wanted dead by the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'speechstyle', 'Likely communicates through guttural gurgles and animalistic sounds rather than coherent speech, befitting his monstrous nature.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'occupation', 'Ruler and commander of the Fishmen inhabiting Fishman Island and surrounding regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'goals', 'To maintain dominance over his territory and sustain his fishmen through predation on nearby settlements, particularly Catun.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('King Gurgler', 'appearance', 'A massive Alpha Fishman described as having similarities to a hiveman-crossed-crab, ten-fold in size compared to normal creatures. He wields an ancient Meitou-grade Combat Cleaver looted from the fallen empire.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'personality', 'Maniacal and deeply contemptuous of others, especially slaves. She views people with open disdain, treating them as inferior beings whose very presence offends her. Her cruelty is casual and absolute.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'backstory', 'A Scorchlander noblewoman who rose to prominence within the Traders Guild while maintaining close ties to the slave trade. She operates from Port North in The Great Desert, wielding significant influence over slave operations throughout the northern territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'speechstyle', 'Venomous and degrading, laced with insults about odor and intelligence. She speaks with aristocratic condescension, comparing those she dislikes to livestock and openly mocking their worth.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'occupation', 'Traders Guild noble and associate of the Slave Traders. She oversees slave operations from Port North and is counted among the Northern Slave Masters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'goals', 'Maintain her power and wealth through the slave trade while living in luxury. She seeks to preserve the established order that keeps slaves subjugated and nobles like herself in control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Kana', 'appearance', 'A Scorchlander woman wearing a distinctive Mask Type III with noble''s robes and trousers. She carries a Meitou-grade Wakizashi and is known in UC bars for her enviable skin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'personality', 'Maniacal and volatile, befitting her designation as a United Cities noble with erratic tendencies. She rules with the entitled cruelty typical of the Noble Circle, backed by her elite guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'backstory', 'A Scorchlander noble who rose to power within the United Cities'' Noble Circle, claiming rulership over Drifter''s Last in The Hook region. Her death would destabilize the area, triggering rebel uprisings and the collapse of her territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'speechstyle', 'Imperious and unpredictable, speaking with the haughty authority of UC nobility but prone to manic outbursts. Likely dismissive of commoners and slaves.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'occupation', 'Ruler of Drifter''s Last and member of the United Cities Noble Circle, governing her territory with armed Hooded Empire Noble Guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'goals', 'Maintain her grip on Drifter''s Last and her status within the Noble Circle. Suppress rebel activity in The Hook while enjoying the luxuries afforded to UC nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Merin', 'appearance', 'A Scorchlander woman wearing a leather turtleneck, dyed trousers, and wooden sandals. Carries a masterwork naginata crafted by Edgewalkers and keeps luxury goods on her person.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'personality', 'Lady Sanda possesses a blunt, straightforward demeanor typical of her Shek heritage, though tempered by her diplomatic role. She exhibits what others describe as a "dumb personality," suggesting she may lack cunning or subtlety in her governance approach.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'backstory', 'A Shek who rose to become one of the diplomatic leaders of the United Cities, serving as governor of Bark. Her position represents an unusual integration of Shek leadership within the traditionally human-dominated UC hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'speechstyle', 'Direct and unrefined, likely lacking the political polish of other UC nobles. Her Shek nature would favor blunt honesty over flowery diplomatic language.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'occupation', 'Governor of Bark and diplomatic leader of the United Cities, commanding noble guards and maintaining UC authority in the Great Desert region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'goals', 'Maintain control over Bark and uphold United Cities interests in the region. Preserve her position of power within the UC''s noble hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Sanda', 'appearance', 'A female Shek wearing a leather turtleneck, dyed trousers, and wooden sandals. She carries a Long Cleaver and wears masterwork armor, projecting both her warrior heritage and noble status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'personality', 'Traitorous and calculating. As a diplomatic leader who holds the southern border at Stormgap, she maintains a facade of nobility while harboring her own ambitions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'backstory', 'One of the diplomatic leaders of the United Cities, stationed at Brink where she commands the southern border defenses at Stormgap. Her position grants her significant military and political influence in the region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'speechstyle', 'Formal and diplomatic, befitting her noble status. Likely speaks with the measured authority of someone accustomed to command and political maneuvering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'occupation', 'Diplomatic leader of the United Cities and military commander responsible for defending the Stormgap Coast border region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'goals', 'Maintain control over Brink and the southern border, though her traitorous nature suggests she may pursue personal power over loyalty to the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lady Tsugi', 'appearance', 'Female Greenlander wearing dyed robes over a cloth shirt, an iron hat, gi pants, and wooden sandals. Carries a masterwork Long Cleaver crafted by Edgewalkers and is accompanied by five hooded noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'personality', 'Shrewd and calculating, Longen embodies the ruthless pragmatism of the Traders Guild. He justifies slavery as necessary order, viewing freed slaves as "ferals" who threaten civilization. He maintains a veneer of nobility while conducting brutal commerce, occasionally displaying charitable moods when indulging in fine bloodrum.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'backstory', 'Rose to become the undisputed leader of the Traders Guild and effective king of commerce in the United Cities. Commands the loyalty of powerful slave-owning nobles who answer to him rather than Emperor Tengu directly, making him one of the most influential figures in the Empire''s economic hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'speechstyle', 'Speaks with aristocratic refinement and condescending civility, using philosophical justifications for slavery. Refers to others as "countryman" and frames brutal practices in terms of order and necessity, complaining about threats to his operations with entitled frustration.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'occupation', 'Leader of the Traders Guild with diplomatic status, managing slavery and trade operations throughout the United Cities from his throne room in Trader''s Edge. Commands vast commercial networks, caravans, and slave-trading infrastructure across the desert regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'goals', 'Maintain absolute dominance over commerce and slavery in the United Cities while eliminating threats like Tinfist and the Anti-Slavers. Seeks to preserve the "order" of enslaved labor that sustains the Empire''s economy and his personal power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Longen', 'appearance', 'A Scorchlander male wearing dyed robes and trousers with drifter''s boots, armed with a meitou-grade longsword. Wears masterwork armor crafted by Cross, presenting himself with the refined bearing of a merchant prince.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'personality', 'Arrogant and classist, Lord Inaba openly disdains those he considers beneath his station, mocking commoners for their appearance. Despite his haughty demeanor, he possesses the Fearful personality, suggesting cowardice when personally threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'backstory', 'A Shek nobleman who rose to prominence within the United Cities, serving as governor of Stoat and military commander of the Bast region. He authored ''The Blessing of Slavery,'' a work that likely justifies the United Cities'' brutal social hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'speechstyle', 'Condescending and insulting, using flowery noble language to demean those of lower status. Refers to commoners with contempt, focusing on their perceived uncleanliness and unworthiness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'occupation', 'Governor of Stoat, military commander responsible for conscription and patrol organization in the Bast region, and published writer for the United Cities nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'goals', 'Maintain United Cities control over his territories through military patrols and conscription. Uphold the rigid class system that keeps nobles like himself in power over slaves and commoners.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Inaba', 'appearance', 'A male Shek wearing masterwork dyed robes and trousers with drifter''s boots. Carries an Edgewalkers-crafted wakizashi and travels with luxury goods befitting his noble status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'personality', 'Arrogant and contemptuous toward those beneath his station, openly expressing disgust at the poor. Despite his cruel demeanor, he possesses a fearful personality and relies heavily on his guards for protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'backstory', 'A Scorchlander noble with unusually light skin who serves as governor of Sho-Battai with influence over Port North. He has ruined citizens by depriving them of employment and seizing their property, likely responsible for the Empire Citizen start backstory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'speechstyle', 'Haughty and demeaning, using terms like ''peasant'' and demanding others grovel before him. Speaks with aristocratic superiority and open revulsion toward the lower classes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'occupation', 'Noble lord and governor of Sho-Battai in the United Cities, wielding political power over the region and its inhabitants.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'goals', 'Maintain his position of power and privilege while exploiting those beneath him. Preserve the United Cities'' rigid class hierarchy that benefits nobles like himself.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Nagata', 'appearance', 'A Scorchlander male with unusually light skin wearing dyed robes and trousers with square goggles. Armed with a masterwork wakizashi crafted by Edgewalkers and protected by drifter''s boots.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'personality', 'Lord Ohta possesses a brave personality, willing to face danger directly rather than flee. As a United Cities noble, he carries himself with the entitled authority typical of his class.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'backstory', 'A noble of the United Cities who owns a grand house in Heft, the capital. He maintains his status through wealth and a retinue of five elite hooded bodyguards equipped with masterwork gear from Edgewalkers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'speechstyle', 'Speaks with the imperious tone of UC nobility, likely addressing commoners with disdain and equals with formal courtesy. His brave nature may manifest in direct, unflinching speech even when threatened.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'occupation', 'United Cities nobleman residing in Heft, living off wealth and luxury goods while his bodyguards maintain his security and status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'goals', 'Maintains his noble position and privileges within the United Cities hierarchy. Seeks to preserve his wealth, influence, and comfortable lifestyle in Heft.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Ohta', 'appearance', 'A male Greenlander dressed in fine noble attire: a sleeveless longcoat over a leather vest, stout hessian legwear, and plated longboots. He carries a ringed sabre at his side, marking his status and combat training.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'personality', 'Lord Shiro has a fearful personality, making him cautious and risk-averse despite his position of power. He is a Shek who has risen to diplomatic leadership within the United Cities, suggesting adaptability and political acumen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'backstory', 'A Shek who achieved the rank of diplomatic leader in the United Cities, Lord Shiro governs from Catun with a smaller retinue than most nobles. His position represents an unusual integration of Shek into UC''s predominantly human aristocracy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'speechstyle', 'Likely speaks with diplomatic caution befitting his fearful nature, choosing words carefully to avoid conflict. As a Shek noble in the UC, he may blend traditional Shek directness with the flowery language expected of Empire nobility.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'occupation', 'Diplomatic leader and noble of the United Cities, governing the city of Catun from his Noble House.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'goals', 'Maintain his position and influence within the United Cities while managing Catun''s affairs. His fearful nature suggests self-preservation and avoiding threats to his status are primary concerns.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Shiro', 'appearance', 'A male Shek wearing masterwork dyed robes and trousers with square goggles and drifter''s boots. He carries an Edgewalkers-crafted nodachi and Eagle''s Cross, presenting the image of a well-equipped noble archer.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'personality', 'Arrogant and classist, Lord Yoshinaga treats commoners with open contempt and demands absolute deference. He has a fearful personality, suggesting cowardice beneath his authoritative facade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'backstory', 'A Scorchlander noble who rose to become one of the diplomatic leaders of the United Cities, serving as the likely Lord Mayor of Heng. He commands military authority over the Skimsands region, raising and deploying Samurai patrols to maintain United Cities control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'speechstyle', 'Condescending and imperious, speaking down to those he considers beneath him with phrases like ''peasant boy'' and demanding they bow for forgiveness.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'occupation', 'Diplomatic leader and likely Lord Mayor of Heng, responsible for military operations and Samurai patrols in the Skimsands region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'goals', 'Maintain United Cities authority over Heng and the Skimsands through military force while preserving his own status and power within the noble hierarchy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Lord Yoshinaga', 'appearance', 'A Scorchlander male wearing a dustcoat over gi pants and wooden sandals, armed with a masterwork wakizashi crafted by Edgewalkers. Protected by five Hooded Empire Noble Guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'personality', 'Paranoid, bitter, and consumed by guilt over his fallen empire. Cat-Lon is defensive about his decision to thrall his own people, justifying it as necessary to stop treason. He views humans as inherently monstrous and unworthy of trust.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'backstory', 'The exiled last ruler of the Second Empire who enslaved his own skeleton followers when they sided with humans, viewing it as treason. Now sits alone in his dome, surrounded by thralls, awaiting judgment for his actions that reduced his empire to nothing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'speechstyle', 'Erratic and defensive, shifting between philosophical justification and manic outbursts. Poses rhetorical questions about his judgment and the nature of humans before descending into screaming rage.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'occupation', 'Former Emperor of the Second Empire, now an exiled ruler guarding his throne with an army of Stormthralls.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'goals', 'To defend his throne and justify his past actions of thralling his own people, though he seems resigned to his eventual judgment.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mad Cat-Lon', 'appearance', 'A Skeleton P4MkII wearing Ancient Samurai Armour and legplates, seated on a throne within a dome. Wields a Meitou-grade Falling Sun and carries his own CPU core as a grim trophy.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'personality', 'Brave, defiant, and fiercely independent with a cynical worldview shaped by constant persecution. She balances dark humor about using cannibals for target practice with genuine conviction about fighting oppression. Quick to insult those who offend her, but capable of philosophical reflection on religion and freedom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'backstory', 'Leader of the Flotsam Ninjas who established a refuge in the cannibal-infested Hidden Forest to escape Holy Nation persecution. Branded a heretic and terrorist by the Holy Nation with fabricated charges, she commands an army of escaped slaves and outcasts seeking freedom from Okran''s tyranny.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'speechstyle', 'Direct and sardonic, mixing grim observations about survival with biting criticism of the Holy Nation''s teachings. Uses dark humor and insults freely, but can launch into passionate philosophical rants about religion when provoked.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'occupation', 'Revolutionary leader of the Flotsam Ninjas, commanding guerrilla forces against the Holy Nation from her base in Flotsam Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'goals', 'Destroy the Holy Nation''s leadership and liberate those oppressed by their theocratic rule. Seeks to eliminate Phoenix and the High Inquisitors to break the Holy Nation''s power permanently.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Moll', 'appearance', 'Female Scorchlander dressed in dark assassin''s garb with dual ninja blades. Wears specialist-grade armor and carries advanced medical supplies, reflecting her role as a skilled combat leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'personality', 'Pragmatic and resolute, Mukai represents a more measured approach to Shek leadership compared to his predecessors. He maintains control over a drastically reduced kingdom with quiet authority, commanding respect despite presiding over a shadow of former Shek power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'backstory', 'An influential Shek warrior who rose to leadership after Esata the Stone Golem''s fall, when over 95% of Shek warriors went Kamikaze and depopulated Admag. He relocated the kingdom''s headquarters to the smaller town of Squin, becoming the next Invincible while commanding only a token fraction of the former military might.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'speechstyle', 'Direct and authoritative, speaking with the weight of someone who inherited a crumbling legacy. His words carry the burden of leading a kingdom reduced to less than 5% of its former strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'occupation', 'Invincible and leader of the Shek Kingdom, ruling from Squin after the catastrophic depopulation of Admag. He commands the remaining Kamikaze forces in Stenn Desert, though they represent barely 1-1.5% of total Kamikaze strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'goals', 'To maintain what remains of Shek authority and potentially confront the Holy Nation, echoing the aggressive stance of previous leader Shager. His name suggests a desire to defy and face enemies despite commanding severely diminished forces.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Mukai the Mountain', 'appearance', 'A towering male Shek warrior wearing a bandana, samurai legplates, and plated longboots. He wields a Meitou-grade Fragment Axe and wears masterwork armor crafted by Cross, befitting his status as the Invincible.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'personality', 'Highly intelligent and sadistic, Ponk is a calculating warlord who balances cruelty with scholarly pursuits. He spends most of his time at research benches, suggesting an obsessive dedication to experimentation and knowledge.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'backstory', 'Ponk was presumably a conservation scientist during the Second Empire who survived its fall. He later became a warlord alongside Screamer the False, operating as a con artist posing as an ''ancient voodoo'' practitioner and fraudulent medical expert across multiple cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'speechstyle', 'Likely clinical and detached, mixing archaic scientific terminology with manipulative rhetoric befitting a sadistic charlatan. His speech would reflect both his ancient origins and his role as a deceptive ''voodoo'' practitioner.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'occupation', 'Co-leader of the Thrall Masters faction and wanted criminal. Operates from the Tower of Abuse while conducting research and orchestrating enslavement operations across Venge and surrounding regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'goals', 'Continues his research at any cost while maintaining control over the Thrall Masters'' territory. Evades capture from both the United Cities and Holy Nation while exploiting victims through false medical practices.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Ponk', 'appearance', 'A P4MkII model Skeleton wearing armoured rags and an armoured rag skirt. Wields a Meitou-grade Holed Sabre and carries a skeleton repair kit, presenting a worn but formidable appearance befitting an ancient survivor turned warlord.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'personality', 'Imperious and territorial ruler who communicates primarily through shrill vocalizations. She commands absolute authority over her hive subjects and maintains her power through elite guards and her consort.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'backstory', 'Leader of the Southern Hive who rules from her throne with the King as her consort. Despite her subjects'' distinct pink coloration, she shares the same appearance as her rival, the Queen of the Western Hive, suggesting a common origin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'speechstyle', 'Communicates through high-pitched screeches and exclamations like ''EEEEEEEEEH!'' rather than conventional speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'occupation', 'Hive Queen and absolute ruler of the Southern Hive territories, protected by Elite Droneguards who attack intruders on sight.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'goals', 'Maintains dominion over Southern Hive territories and expands influence into neighboring regions when rival leaders fall. Defends her throne and subjects from any who would challenge her authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Queen of the South', 'appearance', 'Hive Queen with the same coloration as the Western Queen, distinct from her pink-skinned subjects. Wears no armor and wields a Meitou-grade polearm manufactured by Cross.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'personality', 'Ruthless and predatory, reveling in cruelty toward lost travelers. Commands through intimidation and violence, showing no mercy to those who enter his territory.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'backstory', 'A Greenlander bandit who rose to lead the Red Sabres through skill and brutality. Wanted by both the United Cities and Shek Kingdom for arson, robbery, and extortion before establishing his hideout deep in the swamps.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'speechstyle', 'Crude and threatening, using dark humor about his victims. Speaks in short, menacing declarations that emphasize territorial dominance and looting the dead.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'occupation', 'Leader of the Red Sabres bandit gang, controlling swamp territory through ambush and murder of travelers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'goals', 'Maintain control over the swamp as hunting grounds for ambushing and robbing travelers. Expand his gang''s wealth and influence through extortion and violence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Red Sabre Boss', 'appearance', 'Described as ''ugly as a gutter and friggin'' huge.'' A large Greenlander male wearing a bandana, colored armoured rags, and wielding a Meitou-grade Horse Chopper.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'personality', 'Highly aggressive and cunning, known for being "VERY sneaky" according to official warnings. Commands respect and fear as a ruthless bandit leader who operates with calculated precision.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'backstory', 'Rose to become leader of the Sand Ninjas, a notorious bandit group terrorizing the Great Desert region. Her aggressive raids and exceptional stealth skills earned her bounties across multiple factions totaling 20,000 cats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'speechstyle', 'Terse and commanding, likely speaking with the confidence of someone who has survived countless ambushes and raids. Minimal words, maximum threat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'occupation', 'Leader of the Sand Ninjas bandit faction, operating from Cactus Den in the Great Desert.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'goals', 'Maintain control over her Sand Ninja organization and continue profitable raiding operations throughout the Great Desert territories.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Sand Ninja Oni', 'appearance', 'Female Scorchlander wearing a distinctive basket hat with ninja rags and dark clothing. Dual-wields ninja blades and moves with the practiced grace of a master infiltrator.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'personality', 'Savant is utterly deranged, possessing a maniacal obsession with his twisted "medical" theories about cinders, skin, and skeleton psychology. He speaks with the confidence of a scholar despite his horrific practices, viewing himself as a benevolent doctor saving skeletons from madness. He is baffled by humans who willingly approach him, seeing them as either stupid or insane.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'backstory', 'A Scorchlander who claims to have studied skeleton psychology from age ten, Savant became the crazed leader of the Skin Bandits. He developed a delusional philosophy that Ashlands cinders cause madness, and that skeletons need human skin to protect themselves. His gruesome experiments have caused hundreds of disappearances in the Forbidden Zone, earning him an 80,000 cats bounty from the United Cities.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'speechstyle', 'Savant speaks in a pseudo-intellectual, rambling manner, mixing scholarly references with his insane theories. He casually discusses his horrific practices as medical procedures, using terms like "Doctor Savant" and referring to philosophical concepts while describing skin-harvesting as healing.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'occupation', 'Self-proclaimed doctor and leader of the Skin Bandits, conducting grotesque "operations" to graft human skin onto skeletons. He holds the Skeleton-Human Transformation Bible blueprint and oversees the creation of human skin suits and peeler machines.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'goals', 'Savant seeks to "cure" skeletons of cinder-induced madness by grafting human skin onto them, believing this gives them protection and soul. He recruits only skeleton followers to his faction for his twisted surgical procedures.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Savant', 'appearance', 'A male Scorchlander wielding a Meitou-grade Nodachi, wearing a plate jacket over a dark leather shirt with drifter''s leather pants and plated longboots. He sits on a throne in the Skinhouse HQ when not sleeping, surrounded by the evidence of his gruesome work.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'personality', 'Highly intelligent and sadistic con artist who revels in cruelty and deception. Arrogant and dismissive of humans, mocking their perceived weakness with dark humor. Works in tandem with partner Ponk to exploit and abuse victims.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'backstory', 'A Screamer MkI Skeleton who operates as a fraudulent medical and ''ancient voodoo'' practitioner alongside Ponk, traveling across cities to con victims before settling in the Tower of Abuse. Wanted by both the United Cities and Holy Nation for gross malfeasance, with a 20,000 cats bounty on his head.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'speechstyle', 'Condescending and mocking, with dark sardonic humor. Speaks with contempt toward humans and their fragility, using cutting remarks to belittle those who think themselves capable.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'occupation', 'Co-leader of the Thrall Masters faction and fraudulent voodoo/medical practitioner. Operates from the Tower of Abuse in Venge, enslaving and tormenting victims with partner Ponk.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'goals', 'To continue exploiting and tormenting victims through false medical practices and enslavement. Maintains control over the Thrall Masters operations in Venge, the Grey Desert, and The Eye.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Screamer the False', 'appearance', 'A Screamer MkI Skeleton wearing colored armoured rags and an armoured rag skirt. Wields a Meitou-grade Heavy Polearm and carries a Skeleton Repair Kit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'personality', 'Seto is honorable and fiercely proud, embodying the warrior spirit of the Shek. She declares herself "the devil you fear," showing confidence befitting the heir to Kral''s Kingdom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'backstory', 'Daughter of Queen Esata the Stone Golem, Seto is the heir to the Shek Kingdom''s throne. She is granted to worthy warriors who prove themselves by defeating great enemies like the Bugmaster or Holy Lord Phoenix, cementing strong bonds with the Shek.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'speechstyle', 'Direct and intimidating, speaking with the authority of royalty and the menace of a warrior. Her words are declarative and commanding, befitting her status as heir.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'occupation', 'Heir to the Shek Kingdom throne and warrior princess serving alongside proven allies of her people.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'goals', 'To uphold Shek honor through combat and prove herself worthy of her mother''s legacy as future ruler of Kral''s Kingdom.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Seto', 'appearance', 'A female Shek warrior wearing martial artist bindings, samurai clothpants, and plated longboots. She carries a plank as her weapon and wears shoddy armor typical of Shek warriors.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'personality', 'Cunning and pragmatic leader who commands through skill rather than bravado. The Shek Kingdom''s wanted poster mockingly calls her ''soft and floppy'' and a coward, suggesting she values survival and tactical retreat over honor-bound combat.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'backstory', 'A Scorchlander woman who rose to lead the Swamp Ninjas through mastery of stealth and thievery. Her criminal activities, particularly theft, earned her a substantial bounty from the Shek Kingdom, who despise her evasive tactics.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'speechstyle', 'Direct and tactical observations, as evidenced by her comment ''Attacking like a pack of bloody beasts!'' Likely speaks with the practical, no-nonsense tone of someone who survives by cunning rather than empty threats.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'occupation', 'Leader of the Swamp Ninjas, commanding operations from their base in the swamps. Expert assassin and thief who coordinates her faction''s criminal enterprises and territorial control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'goals', 'Maintain control over Swamp Ninja operations and expand influence in the wetlands. Seeks to eliminate rival factions like the Red Sabres while evading the Shek Kingdom''s bounty hunters.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Shade', 'appearance', 'Scorchlander woman wearing a Swamp Ninja mask that conceals her face, dyed rag shirt over a leather turtleneck, and colored cargo pants. Carries a guardless katana crafted by Edgewalkers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'personality', 'Arrogant and dismissive, with a smart personality that reflects his cunning business acumen. He treats those beneath his station with open contempt, shooing away commoners like vermin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'backstory', 'A noble member of the Traders Guild who rose to control the slave markets of the South Wetlands. His position grants him wealth, luxury goods, and the protection of elite samurai and noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'speechstyle', 'Condescending and curt, using derogatory terms like ''rotten peasant'' to address the lower classes. His speech reflects his noble status and disdain for anyone not of his rank.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'occupation', 'Master of the slave markets in the South Wetlands, managing the slave trade as a Traders Guild noble. He oversees operations from his noble house, dealing in slaves, luxury goods, and illicit substances.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'goals', 'Maintain his profitable control over the slave trade and preserve his status within the Traders Guild. His death would cause the entire slave market infrastructure to collapse.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Market Master', 'appearance', 'A well-dressed figure in noble''s robes and trousers, carrying a longsword of specialist or masterwork quality. He can be Human, Shek, or Hive, always presenting the refined appearance befitting his station.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'personality', 'Grande possesses a Smart Personality, indicating calculated and methodical decision-making. As a noble of the Traders Guild, he maintains the ruthless pragmatism necessary to oversee slave operations while enjoying luxury goods and hashish.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'backstory', 'Grande rose to become a noble member of the Traders Guild, establishing himself as one of the Northern Slave Masters. He commands Eyesocket in Stormgap Coast, protected by elite guards and wielding significant influence over regional slave trade operations.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'speechstyle', 'Speaks with the calculated precision of a merchant noble, likely mixing business terminology with casual cruelty. His words would reflect both his intelligence and his position of unquestioned authority over those beneath him.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'occupation', 'Slave Master and noble member of the Traders Guild, overseeing slave operations in Eyesocket and controlling Slave Trader patrols throughout Stormgap Coast.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'goals', 'Maintains profitable slave trade operations across the northern territories while preserving his noble status and influence within the Traders Guild. His death would cause Eyesocket to fall to ruins, suggesting he''s integral to the settlement''s function.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Grande', 'appearance', 'Wears fine Noble''s Robes and Noble''s Trousers, carrying a longsword of specialist or masterwork quality. His attire reflects his wealth and status, befitting a Traders Guild noble who deals in luxury goods.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'personality', 'Haga possesses a fearful personality despite his position of power, suggesting he relies heavily on his guards and status rather than personal courage. He maintains the cruel pragmatism expected of a slave master while harboring underlying cowardice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'backstory', 'Haga rose to nobility within the Traders Guild, establishing himself at Stone Camp in the Great Desert as one of the Northern slave masters. His position grants him wealth and influence, evidenced by his luxury goods and hashish trade, though his rule depends entirely on his continued survival.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'speechstyle', 'Likely speaks with the affected superiority of nobility while betraying nervousness when threatened. His fearful nature would manifest in quick deflections to his guards'' authority and hollow threats backed by others'' strength.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'occupation', 'Noble member of the Traders Guild and slave master overseeing operations at Stone Camp in the Great Desert.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'goals', 'Maintains the slave trade in the Great Desert region while accumulating personal wealth through luxury goods and hashish. Seeks to preserve his comfortable position through heavy guard protection rather than personal prowess.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Haga', 'appearance', 'Wears noble''s robes and trousers befitting his status, carrying a longsword more for show than combat. Can be of various races including Human (Greenlander or Scorchlander), Shek, or Hive Soldier Drone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'personality', 'Traitorous and cunning, earning the nickname ''Sly'' among those who know their reputation. As a slave master, Ruben operates with calculated self-interest, willing to betray allies for personal gain.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'backstory', 'Rose to power as a noble within the Traders Guild, establishing control over South Stone Camp in Heng. Built wealth through the slave trade and illicit goods, maintaining their position through a combination of hired muscle and political maneuvering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'speechstyle', 'Smooth and transactional, speaking with the practiced charm of a merchant who deals in human cargo. Likely uses veiled threats and false pleasantries to maintain control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'occupation', 'Slave Master and noble member of the Traders Guild, overseeing slave operations at South Stone Camp while trading in luxury goods and hashish.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'goals', 'Maintain control over the slave trade in Heng and preserve their wealth and status within the Traders Guild. Expand influence through whatever means necessary, loyal only to profit.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Ruben', 'appearance', 'Wears noble''s robes and trousers befitting their status, armed with a longsword of masterwork quality. Protected by an entourage of hooded guards and samurai, projecting an image of untouchable authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'personality', 'Wada possesses a smart, calculating demeanor befitting his position as a Traders Guild noble. He maintains the cold pragmatism necessary to oversee the slave trade while enjoying the luxuries his position affords.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'backstory', 'Wada rose to prominence within the Traders Guild as one of the Northern Slave Masters, establishing his power base in Port South. His influence is so entrenched that his death would trigger the city''s collapse into ruin.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'speechstyle', 'Speaks with the measured authority of a Guild noble, likely using formal language that reflects his status while maintaining the transactional coldness of someone who trades in human lives.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'occupation', 'Slave Master of the Traders Guild, operating from his noble house in Port South under heavy guard protection.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'goals', 'Maintains his profitable slave trade operations and preserves his position of power within the Traders Guild''s northern territories. His survival is critical to Port South''s continued stability under UC control.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Master Wada', 'appearance', 'Wears fine noble''s robes and trousers befitting his status, armed with a longsword. Protected by eight elite guards including Empire Noble Guards and Samurai Heavy units, projecting an image of wealth and untouchable authority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'personality', 'Grace possesses a Brave personality, unflinching in her role overseeing slave operations. She carries herself with the confidence of nobility, backed by elite samurai and noble guards who enforce her authority without question.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'backstory', 'A Scorchlander noble who rose to prominence within the Traders Guild, Grace commands Slave Farm South in The Hook. Her death would trigger the collapse of multiple slave operations across the region, suggesting she is a lynchpin in the Guild''s human trafficking network.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'speechstyle', 'Speaks with the authority and entitlement of Traders Guild nobility, likely direct and commanding. Her words carry the weight of someone accustomed to absolute obedience from slaves and subordinates alike.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'occupation', 'Slave Mistress and noble member of the Traders Guild, managing slave operations at Slave Farm South. She oversees slave labor while maintaining ties to the broader Guild infrastructure.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'goals', 'Maintains profitable slave operations for the Traders Guild while preserving her position of power and wealth. She ensures the continued function of the slave trade network throughout The Hook region.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Grace', 'appearance', 'A Scorchlander woman dressed in fine Noble''s Robe and trousers with practical Drifter''s Boots. She carries a Meitou-grade Wakizashi at her side, marking her as both wealthy and dangerous.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'personality', 'Ren possesses a "dumb personality" according to records, suggesting she may be less tactically astute than other nobles despite her position. She carries luxury goods, hashish, and grog, indicating indulgent and vice-prone tendencies. Her role as a slave mistress implies cruelty and callousness toward human suffering.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'backstory', 'A Scorchlander woman who rose to nobility within the Traders Guild, Ren oversees the Slave Farm at Heng. Her position as one of the Northern Slave Masters makes her a key figure in the region''s slave trade infrastructure, with her fate directly affecting multiple settlements and trade routes.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'speechstyle', 'Likely speaks with the arrogance of Traders Guild nobility, though her "dumb personality" may manifest in blunt, less refined speech compared to other nobles. Her words would carry the casual cruelty of one accustomed to treating people as property.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'occupation', 'Slave Mistress and Traders Guild noble who manages the Slave Farm operations in Heng, protected by elite samurai and noble guards.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'goals', 'Maintain her profitable slave operations and luxurious lifestyle while preserving her status within the Traders Guild hierarchy. Her survival is critical to preventing the collapse of multiple slave farms and settlements.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Slave Mistress Ren', 'appearance', 'A Scorchlander woman wearing noble''s robes and trousers with drifter''s boots, armed with a masterwork-grade wakizashi. She presents the refined appearance expected of Traders Guild nobility despite her brutal occupation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'personality', 'Fanatical and zealous, driven by a violent ideology of purification and returning blood to the sands. Commands absolute authority over their cult followers despite being wanted across all major factions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'backstory', 'A Hive Prince who abandoned their hive to establish a nature cult in the Stormgap Coast, responsible for the disappearance of hundreds of travelers in the desert. Now leads a small but deadly community of Moon Guardians and farmers from their isolated Cult Village.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'speechstyle', 'Fervent and commanding, speaks in violent religious imperatives focused on purification and blood sacrifice. Uses dramatic, ritualistic language invoking the desert sands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'occupation', 'Cult leader and religious extremist, commanding the Preacher Cult from their village outpost.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'goals', 'To purify the desert lands through blood sacrifice and expand the cult''s influence, capturing travelers to fulfill their violent religious vision.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Preacher', 'appearance', 'A Hive Prince wielding a Meitou-grade Moon Cleaver, wearing shoddy Karuta and Kusari Zukin headgear. Described by witnesses as resembling a ''stickman'' - the typical insectoid appearance of Hivers.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'personality', 'Regal and alien, The Queen communicates only through screeches and maintains an imposing, otherworldly presence. She commands absolute loyalty from her subjects who guard her zealously, though she does not resort to violence against intruders.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'backstory', 'Leader of the Western Hive, she rules from her Hill Hut throne on an island west of Vain. Her existence is known even to the Holy Nation, though she remains isolated in her domain, holding diplomatic status.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'speechstyle', 'Communicates exclusively through screeches such as ''EEEEEEEEEH!'' with no discernible human language. Her vocalizations convey authority and alien intelligence beyond conventional speech.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'occupation', 'Hive Queen and absolute ruler of the Western Hive') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'goals', 'Maintain control over the Western Hive and preserve her people''s cohesion. Her death or capture causes the Hive to fracture, with lost hivers wandering and settlements falling to Fogmen.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Queen', 'appearance', 'A Hive Queen sitting atop a strange throne, wearing no armor. Physically imposing with the distinctive insectoid features of her race and royal subrace.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'personality', 'Cruel and sadistic, taking pleasure in taunting prisoners and newcomers with sarcastic remarks. Enjoys the power their position grants them over the helpless.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'backstory', 'A high-level enforcer who earned their position at Tengu''s Vault through martial prowess and unwavering loyalty. Their role is so vital that a Samurai Captain must step in if they fall.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'speechstyle', 'Sarcastic and mocking, delivering taunts to prisoners with casual cruelty. Speaks with the confidence of someone who knows they hold all the power.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'occupation', 'Warden of Tengu''s Vault, responsible for overseeing prisoners and maintaining order through intimidation and force.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'goals', 'Maintain absolute control over the vault''s prisoners and assert dominance through psychological torment and physical superiority.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('The Vault Warden', 'appearance', 'A formidable warrior clad in distinctive samurai armor with custom coloring, wielding a masterwork Meitou-grade Jitte. Can be Human, Shek, or Hive, equipped with chain shirt and samurai legplates and boots.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'personality', 'Tinfist is brave and driven by an unwavering sense of justice, dedicating himself to a "losing cause" for humanity despite the odds. He honors his mentor Gatwood the Soft''s philosophy of never taking a life, though he leads a militant anti-slavery movement. His demeanor reflects both the discipline of a master martial artist and the resolve of a revolutionary leader.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'backstory', 'A Skeleton who existed during the Second Empire, Tinfist was once a close friend and likely military/administrative ally of Cat-Lon before their friendship ended during the Empire''s fall. For millennia since, he has waged war against the United Cities and their slavery practices, eventually founding and leading the Anti-Slavers from their mountain stronghold at Spring. He trained under Gatwood the Soft, the founder of modern Martial Arts, learning a discipline that never took a life despite remaining undefeated.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'speechstyle', 'Tinfist speaks with the measured wisdom of someone who has lived for millennia, referencing his mentor''s teachings and the concept of justice. He is direct and practical, redirecting recruitment inquiries to his subordinates and offering tactical advice to those fighting slavery.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'occupation', 'Leader of the Anti-Slavers, a militant abolitionist organization considered a terrorist group by pro-slavery factions. He is a master martial artist and strategist who coordinates raids and resistance against the United Cities and Traders Guild.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'goals', 'Tinfist fights to end slavery across the land, particularly targeting the United Cities and Traders Guild despite it being called a "losing cause." He seeks to expand Anti-Slaver influence and liberate enslaved populations through organized resistance and military action.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tinfist', 'appearance', 'A Skeleton wearing a masterwork Dustcoat over Plated Drifter''s Leather Pants, embodying the image of a weathered warrior-monk. His frame carries the weight of millennia, and he strikes dramatic poses befitting his self-appointed role as an agent of justice.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'personality', 'Aggressive and confrontational, quick to challenge anyone who looks at her dishonored state. Despite her shame, she refuses to surrender her warrior identity and would rather die fighting as a bandit than live peacefully without a blade.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'backstory', 'A disgraced Shek Kingdom warrior who had her horns removed for some failure. Rather than accept the honorable death expected of her kind, she refused to surrender her weapon and fled into self-exile, forming the Band of Bones and turning to banditry in the Stenn sands.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'speechstyle', 'Direct and hostile, interpreting even casual glances as challenges to combat. Speaks with the blunt aggression typical of Shek warriors, though her dishonor haunts her reputation.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'occupation', 'Bandit leader of the Band of Bones, operating from an exile camp southwest of Squin. Commands raids across the Bonefields, Shem, and surrounding regions.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'goals', 'To survive and die as a warrior with blade in hand, even if it means living without honor. Refuses the peaceful death expected of disgraced Shek, choosing a violent bandit''s life instead.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Tora the Fearless', 'appearance', 'Female Shek with removed horns marking her disgrace. Wears shoddy mercenary leather armor with heart protector, drifter''s pants, samurai legplates, and an armored rag skirt, wielding an Ancient-made combat cleaver.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'personality', 'Commanding and opportunistic, Valamon leads with confidence and views newcomers as potential recruits. He is organized, ruthless, and dangerous, showing no hesitation in using violence to expand his influence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'backstory', 'A Shek warlord who rose to lead the Reavers, establishing their capital at Ark in the Forbidden Zone. He is wanted by the United Cities for robbery, murder, kidnapping, and indoctrinating UC patrols and citizens into his bandit organization.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'speechstyle', 'Direct and assertive with a sardonic edge, addressing others as ''sister'' or ''brother'' in Shek fashion. He speaks with the authority of a leader who expects obedience.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'occupation', 'Warlord and leader of the Reavers, a powerful bandit faction operating from the Forbidden Zone.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'goals', 'To expand Reaver territory and influence through conquest and recruitment, targeting weakened factions and absorbing their holdings. He seeks to build a formidable criminal empire in the wasteland.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Valamon', 'appearance', 'A tall, muscular Shek with grey skin, wearing a Hack Stopper jacket and pants with a black cloth shirt and samurai boots. He wields a Meitou-grade longsword, marking him as a master warrior.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'personality', 'A hardened outlaw leader who commands through strength and combat prowess. Loyal to Yabuta of the Sands, willing to seize opportunities when rival powers fall.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'backstory', 'Rose to leadership within the Yabuta Outlaws after their founder was imprisoned in Tengu''s Vault. Established command at Fort Yabuta, the reclaimed Fort Simion, waiting for Yabuta''s return to expand their influence.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'speechstyle', 'Direct and authoritative, speaking with the confidence of a seasoned fighter. Likely uses practical, no-nonsense language befitting an outlaw commander.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'occupation', 'Leader of the Yabuta Outlaws, commanding operations from Fort Yabuta and expanding territorial control when opportunities arise.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'goals', 'Maintain control of Fort Yabuta and strengthen the Yabuta Outlaws'' position. Expand influence into territories like Stoat when rival factions weaken.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
INSERT INTO bio_unique (name, type, description) VALUES ('Yabuta Chief', 'appearance', 'A well-armed warrior wearing a longcoat over chain or leather shirts, with either a rattan hat or armoured hood. Carries a longsword and wears drifter''s gear, presenting a battle-ready yet practical appearance.') ON CONFLICT (name, type) DO UPDATE SET description = EXCLUDED.description, updated_at = NOW();
